using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using Microsoft.Win32;

namespace Aurora {
public sealed class SensorDriverState {public bool Installed,Unknown;public string Version="",Detail="";}
public static class SensorSetup {
    public const string InstallerSHA256="1F519A22E47187F70A1379A48CA604981C4FCF694F4E65B734AAA74A9FBA3032";
    public static SensorDriverState Probe(){var state=new SensorDriverState();try{using(var key=Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services\PawnIO")){if(key==null)return state;state.Installed=true;string path=Environment.ExpandEnvironmentVariables(Convert.ToString(key.GetValue("ImagePath",""))).Trim('"');if(path.StartsWith(@"\SystemRoot\",StringComparison.OrdinalIgnoreCase))path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),path.Substring(12));if(path.StartsWith(@"\??\"))path=path.Substring(4);if(File.Exists(path))state.Version=FileVersionInfo.GetVersionInfo(path).FileVersion;state.Detail=L.T("Driver já instalado; o serviço pode estar parado.","Driver already installed; its service may be stopped.");}}catch(Exception error){state.Unknown=true;state.Detail=error.Message;}return state;}
    public static void Verify(string file){if(!File.Exists(file))throw new FileNotFoundException(L.T("O instalador oficial não acompanha esta pasta.","The official installer is missing from this folder."));using(var sha=SHA256.Create())using(var stream=File.OpenRead(file)){if(BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","")!=InstallerSHA256)throw new InvalidDataException(L.T("O instalador de sensores não passou na verificação de integridade.","The sensor installer did not pass integrity verification."));}var signature=Runner.PS("$s=Get-AuthenticodeSignature -LiteralPath "+Runner.QuotePS(file)+";if($s.Status -ne 'Valid' -or $null -eq $s.SignerCertificate -or $s.SignerCertificate.Subject -notmatch 'O=namazso(?:,|$)'){throw 'Invalid official installer signature'};Write-Output 'OK'",30000);if(signature.Code!=0)throw new InvalidDataException(signature.Output);}
}
public partial class MainWindow {
    void OfferSensorSetup(){if(preview||!startupAccepted||machine==null)return;bool seen=false;try{using(var key=Registry.CurrentUser.OpenSubKey(@"Software\OuO\Appearance"))seen=key!=null&&Convert.ToString(key.GetValue("SensorSetupOffered","0"))=="1";}catch{}if(seen)return;SensorDriverState state=null;Work(T("Checar acesso aos sensores","Check sensor access"),()=>{state=SensorSetup.Probe();return state.Installed?"OK • "+state.Detail:state.Unknown?"AVISO • "+state.Detail:T("Driver de sensores ainda não instalado.","Sensor driver is not installed yet.");},result=>{if(state==null||state.Unknown)return;if(state.Installed){SavePreference("SensorSetupOffered","1");return;}SavePreference("SensorSetupOffered","1");if(!Environment.Is64BitOperatingSystem||machine.Build<7601){ShowToast(T("A preparação dos sensores não está disponível neste sistema. Consulte Sobre.","Sensor setup is not available on this system. See About."));return;}if(Confirm(T("Quer preparar a leitura de temperaturas?\n\nNenhuma instalação do PawnIO foi encontrada. O instalador oficial assinado 2.2.0 permite acesso aos sensores compatíveis. O Windows pedirá permissão de administrador. Você pode cancelar e preparar depois pela Visão geral.\n\nNem todo equipamento informa temperaturas de GPU/VRM.","Set up temperature readings?\n\nNo PawnIO installation was found. The signed official 2.2.0 installer provides access to supported sensors. Windows will request administrator permission. You can cancel and set this up later from Overview.\n\nNot every device exposes GPU/VRM temperatures.")))InstallSensorDriver();});}
    void RunSensorInstaller(){if(preview)return;string file=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Sensors","PawnIO_setup.exe");Work(T("Conferir instalador dos sensores","Verify sensor installer"),()=>{SensorSetup.Verify(file);return "OK";},result=>{if(ResultTone.IsFailure(result)){ShowNotice(result);return;}try{var process=Process.Start(new ProcessStartInfo(file){UseShellExecute=true,Verb="runas",WorkingDirectory=Path.GetDirectoryName(file)});if(process==null){ShowToast(T("Confira a conclusão no instalador e reinicie os sensores.","Check completion in the installer and restart sensors."));return;}Work(T("Preparar driver de sensores","Set up sensor driver"),()=>{using(process){if(!process.WaitForExit(900000))return T("AVISO • O instalador continua aberto. Confira sua conclusão antes de repetir.","WARNING • The installer is still open. Check completion before repeating.");}var installed=SensorSetup.Probe();if(!installed.Installed)return T("AVISO • Instalação não confirmada. Você pode tentar novamente pela Visão geral.","WARNING • Installation was not confirmed. You can retry from Overview.");return "OK • "+T("Driver detectado: ","Driver detected: ")+installed.Version;},done=>{if(!ResultTone.IsFailure(done)&&SensorSetup.Probe().Installed)sensors.Restart();ShowNotice(done);});}catch(System.ComponentModel.Win32Exception ex){ShowNotice(ex.NativeErrorCode==1223?T("Instalação cancelada pelo usuário.","Installation canceled by user."):"ERROR • "+ex.Message);}});}
}
}
